INSERT INTO lessons (module_id, title, description, duration, published_at, position, origin, video_source, youtube_id, video_updated_at, created_at, updated_at) SELECT m.module_id, 'Overview do Fusion Web: por dentro do sistema', 'Uma apresentação rápida por dentro do Fusion Web, para você conhecer como o sistema vai ajudar no dia a dia. Vídeo do canal Infotecsoft.', '2:47', '2026-04-01', 0, 'admin', 'youtube', 'k8rcsfrgcOI', NOW(), NOW(), NOW() FROM modules m WHERE m.system_id = 'fusion-web' AND m.name = 'Primeiros passos' AND NOT EXISTS (SELECT 1 FROM (SELECT youtube_id FROM lessons) x WHERE x.youtube_id = 'k8rcsfrgcOI');
INSERT IGNORE INTO modules (system_id, name, icon, position) SELECT 'fusion-web', 'Frente de caixa (PDV)', 'store', position + 1 FROM modules WHERE system_id = 'fusion-web' AND name = 'Vendas e faturamento';
INSERT INTO lessons (module_id, title, description, duration, published_at, position, origin, video_source, youtube_id, video_updated_at, created_at, updated_at) SELECT m.module_id, 'Por dentro do PDV: como passar uma venda no checkout', 'Como passar as vendas dos clientes no Checkout PDV do Fusion Web. Vídeo do canal Infotecsoft.', '5:11', '2026-04-01', 1, 'admin', 'youtube', 'zYunzi5beaQ', NOW(), NOW(), NOW() FROM modules m WHERE m.system_id = 'fusion-web' AND m.name = 'Frente de caixa (PDV)' AND NOT EXISTS (SELECT 1 FROM (SELECT youtube_id FROM lessons) x WHERE x.youtube_id = 'zYunzi5beaQ');
INSERT IGNORE INTO user_module_access (user_id, module_id, created_at) SELECT a.user_id, p.module_id, NOW() FROM user_module_access a JOIN modules v ON v.module_id = a.module_id AND v.system_id = 'fusion-web' AND v.name = 'Vendas e faturamento' JOIN modules p ON p.system_id = 'fusion-web' AND p.name = 'Frente de caixa (PDV)'
