-- Fusion Web: primeiros vídeos do canal Infotecsoft (overview em "Primeiros passos" e checkout no novo módulo "Frente de caixa (PDV)")
UPDATE modules SET position = position + 1 WHERE system_id = 'fusion-web' AND position > (SELECT p FROM (SELECT position AS p FROM modules WHERE system_id = 'fusion-web' AND name = 'Vendas e faturamento') v) AND NOT EXISTS (SELECT 1 FROM (SELECT module_id FROM modules WHERE system_id = 'fusion-web' AND name = 'Frente de caixa (PDV)') x);
